1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	const PROCESSING_FEE = 5;
13	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
14	
15	const BASE_PREMIUMS: Record<string, number> = {
16	  sword: 100,
17	  amulet: 60,
18	  staff: 80,
19	  potion: 40,
20	  rune: 25,
21	  moonstone: 25,
22	};
23	
24	const COMPONENT_PREMIUM = 25;
25	const BLOCK_SIZE = 3;
26	const BLOCK_PREMIUM = 60;
27	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
28	
29	const CURSE_SURCHARGE_PERCENT = 50;
30	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
31	const HIGH_ENCHANTMENT_THRESHOLD = 5;
32	
33	const percentOf = (amount: number, percent: number): number =>
34	  (amount * percent) / 100;
35	
36	const basePremium = (item: Item): number => BASE_PREMIUMS[item.type] ?? 0;
37	
38	const componentGroupPremium = (count: number): number =>
39	  count === BLOCK_SIZE ? BLOCK_PREMIUM : count * COMPONENT_PREMIUM;
40	
41	const firstInsuranceSurcharge = (base: number): number =>
42	  percentOf(base, FIRST_INSURANCE_SURCHARGE_PERCENT);
43	
44	const roundInMhpcoFavor = (premium: number): number => Math.ceil(premium);
45	
46	const payoutInMhpcoFavor = (payout: number): number => Math.floor(payout);
47	
48	const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);
49	
50	const isMainItem = (item: Item): boolean => !isComponent(item);
51	
52	const countByType = (items: Item[]): Map<string, number> => {
53	  const counts = new Map<string, number>();
54	  for (const item of items) {
55	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
56	  }
57	  return counts;
58	};
59	
60	const componentsTotalByType = (components: Item[]): number =>
61	  [...countByType(components).values()].reduce(
62	    (total, count) => total + componentGroupPremium(count),
63	    0,
64	  );
65	
66	const itemsBasePremium = (items: Item[]): number => {
67	  const components = items.filter(isComponent);
68	  const mainItems = items.filter(isMainItem);
69	  const mainItemsTotal = mainItems.reduce(
70	    (sum, item) => sum + basePremium(item),
71	    0,
72	  );
73	  return mainItemsTotal + componentsTotalByType(components);
74	};
75	
76	const itemSurcharge = (item: Item): number => {
77	  const base = basePremium(item);
78	  const curse = item.cursed ? percentOf(base, CURSE_SURCHARGE_PERCENT) : 0;
79	  const highEnchantment =
80	    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
81	      ? percentOf(base, HIGH_ENCHANTMENT_SURCHARGE_PERCENT)
82	      : 0;
83	  return curse + highEnchantment;
84	};
85	
86	const itemSurcharges = (items: Item[]): number =>
87	  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
88	
89	const LOYALTY_DISCOUNT_PERCENT = 20;
90	const LOYALTY_THRESHOLD_YEARS = 2;
91	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;
92	
93	const loyaltyDiscount = (customer: Customer, base: number): number =>
94	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS
95	    ? percentOf(base, LOYALTY_DISCOUNT_PERCENT)
96	    : 0;
97	
98	const followUpContractDiscount = (contractIndex: number, base: number): number =>
99	  contractIndex > 0 ? percentOf(base, FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT) : 0;
100	
101	const policyModifiers = (
102	  customer: Customer,
103	  contractIndex: number,
104	  base: number,
105	): number =>
106	  firstInsuranceSurcharge(base) -
107	  loyaltyDiscount(customer, base) -
108	  followUpContractDiscount(contractIndex, base);
109	
110	export const quote = (
111	  customer: Customer,
112	  items: Item[],
113	  contractIndex: number,
114	): number => {
115	  const base = itemsBasePremium(items);
116	  const total =
117	    base +
118	    policyModifiers(customer, contractIndex, base) +
119	    itemSurcharges(items) +
120	    PROCESSING_FEE;
121	  return roundInMhpcoFavor(total);
122	};
123	
124	export interface Damage {
125	  itemType: string;
126	  amount: number;
127	}
128	
129	export interface Incident {
130	  cause: string;
131	  damages: Damage[];
132	}
133	
134	export interface ClaimResult {
135	  payout: number;
136	  remainingCap: number;
137	}
138	
139	const DEDUCTIBLE = 100;
140	const CAP_MULTIPLIER = 2;
141	
142	const INSURANCE_VALUES: Record<string, number> = {
143	  sword: 1000,
144	  amulet: 600,
145	  staff: 800,
146	  potion: 400,
147	  rune: 250,
148	  moonstone: 250,
149	};
150	
151	const insuranceValue = (item: Item): number => INSURANCE_VALUES[item.type] ?? 0;
152	
153	const insuranceSum = (items: Item[]): number =>
154	  items.reduce((sum, item) => sum + insuranceValue(item), 0);
155	
156	const HIGH_ENCHANTMENT_REIMBURSEMENT_THRESHOLD = 8;
157	const HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT = 50;
158	
159	const reimbursedAmount = (item: Item, amount: number): number =>
160	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_REIMBURSEMENT_THRESHOLD
161	    ? percentOf(amount, HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT)
162	    : amount;
163	
164	const damagePayout = (damage: Damage, item: Item): number =>
165	  Math.max(0, reimbursedAmount(item, damage.amount) - DEDUCTIBLE);
166	
167	const insuredItemFor = (items: Item[], damage: Damage): Item =>
168	  items.find((item) => item.type === damage.itemType) as Item;
169	
170	const totalDamagePayout = (items: Item[], damages: Damage[]): number =>
171	  damages.reduce(
172	    (sum, damage) => sum + damagePayout(damage, insuredItemFor(items, damage)),
173	    0,
174	  );
175	
176	const validateDamageCounts = (items: Item[], damages: Damage[]): void => {
177	  const insuredCounts = countByType(items);
178	  const damageCounts = new Map<string, number>();
179	  for (const damage of damages) {
180	    const next = (damageCounts.get(damage.itemType) ?? 0) + 1;
181	    if (next > (insuredCounts.get(damage.itemType) ?? 0)) {
182	      throw new Error(
183	        `More ${damage.itemType} damages than insured items in the policy`,
184	      );
185	    }
186	    damageCounts.set(damage.itemType, next);
187	  }
188	};
189	
190	export const claim = (
191	  items: Item[],
192	  incident: Incident,
193	  priorPayouts: number,
194	): ClaimResult => {
195	  validateDamageCounts(items, incident.damages);
196	  const cap = insuranceSum(items) * CAP_MULTIPLIER;
197	  const remainingBefore = cap - priorPayouts;
198	  const rawPayout = totalDamagePayout(items, incident.damages);
199	  const payout = Math.min(payoutInMhpcoFavor(rawPayout), remainingBefore);
200	  return { payout, remainingCap: remainingBefore - payout };
201	};
